; DFMT.S - TEXT FORMATTING AND RENDERING PRIMITIVES
;
; (DASH-MOD WP5: THE OLD UNBOUNDED PRINTAT ROUTINE WAS REMOVED HERE --
; DEAD CODE, SUPERSEDED BY THE BOUNDED SCREENSETCURSOR / SCREENPUTSTRING /
; SCREENPUTCHAR PRIMITIVES AND REFERENCED FROM NOWHERE.)

; FORMATHEX8 - FORMATS AN 8-BIT VALUE AS TWO UPPERCASE SCREEN-CODE HEX DIGITS.
;
; INPUT: A = BYTE VALUE.
; OUTPUT: FMTBUF, FMTBUF+1 = HEX DIGITS (HIGH NIBBLE FIRST). FMTBUF+2 = $00
;         TERMINATOR. (3 OF THE 5 FMTBUF BYTES USED.)
; CLOBBERS: A, Y. PRESERVES X.
FORMATHEX8:
    PHA
    LSR A
    LSR A
    LSR A
    LSR A                    ; A = HIGH NIBBLE
    TAY
    LDA HEXDIGITS, Y
    STA FMTBUF
    PLA
    AND #$0F                 ; A = LOW NIBBLE
    TAY
    LDA HEXDIGITS, Y
    STA FMTBUF+1
    LDA #0
    STA FMTBUF+2
    RTS

; FORMATHEX16 - FORMATS A 16-BIT VALUE AS FOUR UPPERCASE SCREEN-CODE HEX DIGITS.
;
; INPUT: X = VALUE LOW BYTE, Y = VALUE HIGH BYTE.
; OUTPUT: FMTBUF..FMTBUF+3 = HEX DIGITS (HIGH BYTE FIRST). FMTBUF+4 = $00
;         TERMINATOR. (ALL 5 FMTBUF BYTES USED.)
; CLOBBERS: A, X, Y.
FORMATHEX16:
    STX FMTWORK                  ; ZP FMTWORK = VALUE LOW
    STY FMTWORK+1                  ; ZP FMTWORK+1 = VALUE HIGH
    LDA FMTWORK+1
    LSR A
    LSR A
    LSR A
    LSR A
    TAX
    LDA HEXDIGITS, X
    STA FMTBUF
    LDA FMTWORK+1
    AND #$0F
    TAX
    LDA HEXDIGITS, X
    STA FMTBUF+1
    LDA FMTWORK
    LSR A
    LSR A
    LSR A
    LSR A
    TAX
    LDA HEXDIGITS, X
    STA FMTBUF+2
    LDA FMTWORK
    AND #$0F
    TAX
    LDA HEXDIGITS, X
    STA FMTBUF+3
    LDA #0
    STA FMTBUF+4
    RTS

; FORMATDEC16 - FORMATS A 16-BIT UNSIGNED VALUE AS A RIGHT-ALIGNED DECIMAL
; FIELD, SPACE-PADDED TO A FIXED WIDTH OF 5.
;
; A FULL 16-BIT VALUE NEVER EXCEEDS 5 DECIMAL DIGITS (65535), SO THIS FIELD
; CANNOT OVERFLOW; THE FIXED-WIDTH RESULT FILLS ALL 5 FMTBUF BYTES WITH NO
; ROOM FOR A TERMINATOR. CALLERS WRITE THE 5 BYTES AS A BOUNDED FIXED-LENGTH
; FIELD (E.G. SCREENPUTSTRING WITH A MAXIMUM LENGTH OF 5), NOT AS A
; NUL-TERMINATED STRING.
;
; INPUT: X = VALUE LOW BYTE, Y = VALUE HIGH BYTE.
; OUTPUT: FMTBUF..FMTBUF+4 = 5 SCREEN-CODE BYTES, RIGHT-ALIGNED, SPACE-PADDED.
; CLOBBERS: A, X, Y.
FORMATDEC16:
    STX FMTWORK                  ; ZP FMTWORK/FMTWORK+1 = WORKING VALUE, DESTROYED BY DIV10
    STY FMTWORK+1
    LDA #SCREENCODE_SPACE                 ; PRE-FILL WITH SPACES (RIGHT-ALIGN PADDING)
    STA FMTBUF
    STA FMTBUF+1
    STA FMTBUF+2
    STA FMTBUF+3
    STA FMTBUF+4
    LDX #4                   ; WRITE INDEX, STARTS AT THE RIGHTMOST BYTE
@LOOP:
    TXA                       ; DIV10 CLOBBERS X (ITS OWN 16-ITERATION SHIFT
    PHA                       ; COUNTER), SO THE WRITE INDEX MUST BE STACKED
    JSR DIV10                 ; ACROSS THE CALL, NOT LEFT IN X. DIVIDES
                               ; FMTWORK/FMTWORK+1 BY 10 IN PLACE; REMAINDER IN A.
    TAY
    LDA HEXDIGITS, Y          ; DIGITS 0-9 SHARE THE HEX DIGIT TABLE
    STA DIV10REM                   ; STASH DIGIT CHAR (DIV10 HAS ALREADY RETURNED,
                               ; SO ITS SCRATCH BYTE IS FREE)
    PLA
    TAX                       ; RESTORE THE WRITE INDEX
    LDA DIV10REM
    STA FMTBUF, X
    LDA FMTWORK
    ORA FMTWORK+1
    BEQ @DONE                ; QUOTIENT IS ZERO: NO MORE SIGNIFICANT DIGITS
    DEX
    BPL @LOOP                ; BOUNDED: 65535 NEEDS EXACTLY 5 DIGITS, X>=0
@DONE:
    RTS

; PETTOSCREEN - CONVERTS ONE RAW PETSCII BYTE (FROM A PUBLIC API RECORD, E.G.
; DOS_GET_APP_INFO'S NAME FIELD) TO ITS SCREEN-CODE EQUIVALENT FOR A DIRECT
; SCREEN-RAM POKE.
;
; ONLY THE $00-$5F BAND IS CONVERTED (CONTROL/SPACE/DIGIT/PUNCTUATION BYTES
; $00-$3F PASS THROUGH UNCHANGED, UPPERCASE LETTERS AND $40-$5F SYMBOLS ARE
; REBASED BY -$40) -- THE RANGE ACTUAL FILENAMES/APP NAMES USE ON THIS
; PROJECT (SEE THE CC1541 -F UNSHIFTED-PETSCII CONVENTION). BYTES $60 AND
; ABOVE (LOWERCASE/GRAPHICS PETSCII) PASS THROUGH UNCHANGED AS A BOUNDED
; BEST-EFFORT FALLBACK RATHER THAN A FULL 4-BAND PETSCII TABLE: STILL A
; SINGLE BOUNDED SCREEN-RAM POKE, JUST POSSIBLY THE WRONG GLYPH FOR THAT
; INPUT, NEVER UNSAFE.
;
; INPUT: A = RAW PETSCII BYTE.
; OUTPUT: A = SCREEN-CODE BYTE.
; CLOBBERS: A.
PETTOSCREEN:
    CMP #PETSCII_SYMBOL_BASE
    BCC @DONE                 ; < $40: UNCHANGED
    CMP #PETSCII_LOWER_BASE
    BCS @DONE                 ; >= $60: UNCHANGED (FALLBACK)
    SEC
    SBC #PETSCII_SYMBOL_BASE                   ; $40-$5F: REBASE
@DONE:
    RTS

; DIV10 - DIVIDES THE 16-BIT VALUE AT ZP FMTWORK/FMTWORK+1 BY 10, IN PLACE.
;
; BOUNDED BINARY LONG DIVISION: EXACTLY 16 SHIFT ITERATIONS REGARDLESS OF
; MAGNITUDE, NOT UNBOUNDED REPEATED SUBTRACTION.
;
; INPUT: ZP FMTWORK/FMTWORK+1 = DIVIDEND.
; OUTPUT: ZP FMTWORK/FMTWORK+1 = QUOTIENT. A = REMAINDER (0-9).
; CLOBBERS: A, X, ZP DIV10REM.
DIV10:
    LDA #0
    STA DIV10REM                  ; REMAINDER ACCUMULATOR
    LDX #16
@LOOP:
    ASL FMTWORK
    ROL FMTWORK+1
    ROL DIV10REM
    LDA DIV10REM
    SEC
    SBC #DEC_RADIX
    BCC @SKIP
    STA DIV10REM
    INC FMTWORK                  ; SET QUOTIENT BIT
@SKIP:
    DEX
    BNE @LOOP
    LDA DIV10REM
    RTS
